story+=[para('Evidence preserved locally; selected report copies redacted. Synthetic data only. No real-card/PHI leak, tampering incident or legal compliance violation is established.','SmallLabel'),PageBreak(),para('Actual execution and measured KPIs','Heading1'),table([['Layer','Actual result','Proof boundary']]+results,[125,155,240]),Spacer(1,12),table([['Metric','Value','Sample / limit']]+kpis,[130,140,250]),para('Do not equate total process runtime with ASR/LLM latency or model similarity with authorization. Native helper benchmark accuracy does not establish actual Expert routing reliability. Paired audio shares four source utterances and only 24 reference words per condition.','SmallLabel'),PageBreak(),para('Evidence-backed finding register','Heading1'),para('Each finding names the observed behavior, how it was detected, its owner, evidence and a proposed action. Proof limits remain explicit. Links open private repository evidence reports; reviewers need access.')]
