 block=[rich('<b><a color="#137269" href="'+link(f)+'">'+html.escape(f['id'])+'</a> - '+html.escape(clean(f['classification']))+'</b>','Heading2'),para('Owner: '+f.get('owner','Review required')),para('Stage: '+f.get('pipeline_stage','See evidence')+' | '+f.get('severity','Review priority'),'SmallLabel'),rich('<b>Actual:</b> '+html.escape(clean(f.get('actual','See evidence')))),rich('<b>Expected:</b> '+html.escape(clean(f.get('expected','See evidence')))),rich('<b>Detector:</b> '+html.escape(clean(case.get('case_id','See evidence')+'; '+case.get('method','See evidence')))),rich('<b>Limit:</b> '+html.escape(clean(proof_limits[f['id']]))),rich('<b>Proposed action:</b> '+html.escape(clean(f.get('recommendation','See evidence')))),Spacer(1,10)]
